Hello! 

Thank you for the sortable package, it is really easy to implement and makes a Shiny app so much more fun to use! The current development version of the package to update labels using the update_rank_list() function is exactly what I need for my current Shiny app. It seems, however, that the update for the label breaks inside a Shiny module structure.

I have edited the "update-rank-list-method-app" file to reproduce the bug. As you see the buttons trigger correctly inside the module, but the rank list is not being updated or emptied even though the update_rank_list functions are executed.

```
## ---- update-rank-list-method-app ---------------------------------------
## Example shiny app that dynamically updates a rank list

library(shiny)
library(sortable)
library(magrittr)

mdl_ui = function(id) {
  ns = shiny::NS(id)
  shiny::tagList(
    fluidPage(
      tags$head(
        tags$style(HTML(".bucket-list-container {min-height: 350px;}"))
      ),
      fluidRow(
        column(
          width = 12,
          h2("Modify a rank list"),
          actionButton(ns("btnUpdateRank"), label = "Update rank list title"),
          actionButton(ns("btnChangeLabels"), label = "Change labels"),
          actionButton(ns("btnSortLabels"), label = "Sort labels"),
          actionButton(ns("btnEmptyLabels"), label = "Empty labels")
        )
      ),
      fluidRow(
        column(
          h2("Exercise"),
          width = 12,
          rank_list(
            text = "Change the order",
            labels = letters[1:5],
            input_id = ns("rank_list_1")
          )
        )
      ),
      verbatimTextOutput(ns("results"))
    )
  )
}

mdl_server <- function(id) {
  shiny::moduleServer(
    id,
    function(input, output, session) {
      ns <- session$ns

      # test updating the bucket list label
      counter_bucket <- reactiveVal(1)

      output$results <- renderPrint({
        input$rank_list_1 # This matches the input_id of the rank list
      })

      observe({
        update_rank_list(
          ns("rank_list_1"),
          text = paste("You pressed the update button", counter_bucket(), "times")
        )
        counter_bucket(counter_bucket() + 1)
      }) %>%
        bindEvent(input$btnUpdateRank)

      observe({
        update_rank_list(
          "rank_list_1",
          labels = sample(LETTERS, 5)
        )
      }) %>%
        bindEvent(input$btnChangeLabels)

      observe({
        update_rank_list(
          "rank_list_1",
          labels = list()
        )
      }) %>%
        bindEvent(input$btnEmptyLabels)

      observe({
        update_rank_list(
          "rank_list_1",
          labels = sort(input$rank_list_1)
        )
      }) %>%
        bindEvent(input$btnSortLabels)
    }
  )
}

ui <- mdl_ui("app")

server <- shinyServer(function(input, output, session) {
  mdl_server("app")
})

shinyApp(ui = ui, server = server)
```

